export const languageOptions: { id: Language; label: string }[] = [
  { id: "en", label: "US English" }, { id: "zh", label: "CN 中文" }, { id: "es", label: "ES Español" },
  { id: "pt-BR", label: "BR Português" }, { id: "ru", label: "RU Русский" }, { id: "id", label: "ID Indonesia" }, { id: "vi", label: "VN Tiếng Việt" },
];

const LanguageContext = createContext<LanguageContextValue | null>(null);

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<Language>(() => {
    const saved = localStorage.getItem("2pescrow_language") as Language | null;
    return languageOptions.some((option) => option.id === saved) ? saved! : "en";
  });
  const setLanguage = (next: Language) => {
    localStorage.setItem("2pescrow_language", next);
    setLanguageState(next);
  };
  const value = useMemo(
    () => ({
      language,
      setLanguage,
      t: (english: string) =>
        translations[language]?.[english] ??
        extraTranslations[language]?.[english] ??
        dashboardTranslations[language]?.[english] ??
        homeTranslations[language]?.[english] ??
        homeStatusTranslations[language]?.[english] ??
        tradeDocumentTranslations[language]?.[english] ??
        tradeRoomTranslations[language]?.[english] ??
        sharedPageTranslations[language]?.[english] ??
        statusAndNetworkTranslations[language]?.[english] ??
        tradeUiTranslations[language]?.[english] ??
        tronInstallTranslations[language]?.[english] ??
        authAndPagesTranslations[language]?.[english] ??
        english,
    }),
    [language]
  );
  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

export function useLanguage() {
  const context = useContext(LanguageContext);
  if (!context) throw new Error("useLanguage must be used inside LanguageProvider");
  return context;
}
